#!/usr/bin/env bash
# Opens Grafana (kube-prometheus-stack, installed by scripts/deploy-platform.sh)
# of an environment on http://localhost:3001 through a kubectl port-forward,
# after printing its admin credentials (random password generated by the
# chart). Ctrl-C closes it. Grafana has no public address: this is the only way in.
#
# Usage: scripts/grafana.sh staging|prod
#
# Environment:
#   GRAFANA_PORT  local port (default 3001; 3000 is often taken by a local web app)
set -euo pipefail

env="${1:-}"
[[ "$env" == staging || "$env" == prod ]] || { echo "usage: $0 staging|prod" >&2; exit 2; }
PORT="${GRAFANA_PORT:-3001}"
cluster="code-keeper-$env"

aws eks update-kubeconfig --region "${AWS_REGION:-eu-west-3}" --name "$cluster" --alias "$cluster" >/dev/null

secret() {
  kubectl --context "$cluster" -n monitoring get secret monitoring-grafana \
    -o "jsonpath={.data.$1}" | base64 -d
}

echo "Grafana of $env: http://localhost:$PORT"
echo "  user:     $(secret admin-user)"
echo "  password: $(secret admin-password)"
echo "Dashboards: Kubernetes / Compute Resources / Namespace (Pods), namespace code-keeper"
exec kubectl --context "$cluster" -n monitoring port-forward service/monitoring-grafana "$PORT:80"
